  //   13 字段 / 152 位，字段表取自 golden UncacheEntry 的 io_exception_bits_*（与 LoadQueueUncache io_exception_bits_* 逐项相同）
  typedef struct packed {
    logic         uop_exceptionVec_3;
    logic         uop_exceptionVec_4;
    logic         uop_exceptionVec_5;
    logic         uop_exceptionVec_13;
    logic         uop_exceptionVec_19;
    logic         uop_exceptionVec_21;
    logic [6:0]   uop_uopIdx;
    logic         uop_robIdx_flag;
    logic [7:0]   uop_robIdx_value;
    logic [63:0]  fullva;
    logic [63:0]  gpaddr;
    logic         isHyper;
    logic         isForVSnonLeafPTE;
  } lqu_exc_t;

  // lqu_rollback_t：满了回滚用的 redirect（Redirect 在本层被用到的字段）
  //   8 字段 / 86 位，字段表取自 golden LoadQueueUncache 的 io_rollback_bits_*
  typedef struct packed {
    logic         isRVC;
    logic         robIdx_flag;
    logic [7:0]   robIdx_value;
    logic         ftqIdx_flag;
    logic [5:0]   ftqIdx_value;
    logic [3:0]   ftqOffset;
    logic         level;
    logic [63:0]  debug_runahead_checkpoint_id;
  } lqu_rollback_t;

