  endfunction
// END GENERATED

  // 条目的 uncache 请求（7 字段）-> 发往 Uncache 的总线请求（10 字段）：
  //   cmd 恒为读（M_XRD）；data 在读请求里无意义，golden 给 0；id = 条目号（MMIO 路由时
  //   由本模块按选中的条目号填，NC 路由时由仲裁器按 chosen 填）。
  function automatic lqu_ureq_t to_bus_req(lqu_ent_ureq_t r, logic [6:0] id);
    lqu_ureq_t o;
    o.robIdx_flag   = r.robIdx_flag;
    o.robIdx_value  = r.robIdx_value;
    o.cmd           = M_XRD;
    o.addr          = r.addr;
    o.vaddr         = r.vaddr;
    o.data          = 64'h0;
    o.mask          = r.mask;
    o.id            = id;
    o.nc            = r.nc;
    o.memBackTypeMM = r.memBackTypeMM;
    return o;
  endfunction

endpackage

module xs_LoadQueueUncache_core
  import loadqueueuncache_pkg::*;
(
  input  logic                  clock,
  input  logic                  reset,
  // ---- 控制：redirect（冲刷）与 ROB（MMIO 发车条件 / loadMmio 通知）----
  input  logic                  io_redirect_valid,
  input  logic                  io_redirect_bits_robIdx_flag,
  input  logic [7:0]            io_redirect_bits_robIdx_value,
  input  logic                  io_redirect_bits_level,
  input  logic                  io_rob_pendingMMIOld,
  input  logic                  io_rob_pendingPtr_flag,
  input  logic [7:0]            io_rob_pendingPtr_value,
  output logic [LD_W-1:0]       io_rob_loadMmio,
  output logic [7:0]            io_rob_loadMmioUop_robIdx_value [LD_W],
  // ---- 入队：三条 load 流水线 s3 ----
  input  logic [LD_W-1:0]       io_req_valid,
  input  lqu_req_t              io_req_bits [LD_W],
  // ---- 写回：MMIO（只有 2 号口）与 NC（0/1/2 号口）----
  input  logic                  io_mmioOut_ready,
  output logic                  io_mmioOut_valid,
  output lqu_mmio_out_t         io_mmioOut_bits,
  output lqu_raw_t              io_mmioRawData,
  input  logic [LD_W-1:0]       io_ncOut_ready,
  output logic [LD_W-1:0]       io_ncOut_valid,
  output lqu_nc_out_t           io_ncOut_bits [LD_W],
  // ---- Uncache 总线 ----
  input  logic                  io_uncache_req_ready,
  output logic                  io_uncache_req_valid,
  output lqu_ureq_t             io_uncache_req_bits,
  input  logic                  io_uncache_idResp_valid,
  input  logic [6:0]            io_uncache_idResp_bits_mid,
  input  logic [3:0]            io_uncache_idResp_bits_sid,
  input  logic                  io_uncache_resp_valid,
  input  logic [63:0]           io_uncache_resp_bits_data,
  input  logic [3:0]            io_uncache_resp_bits_id,
  input  logic                  io_uncache_resp_bits_denied,
  input  logic                  io_uncache_resp_bits_corrupt,
  // ---- 回滚与异常 ----
  output logic                  io_rollback_valid,
  output lqu_rollback_t         io_rollback_bits,
  output logic                  io_exception_valid,
  output lqu_exc_t              io_exception_bits
);

  redirect_t redirect_now;   // 本拍的 io.redirect
  assign redirect_now = '{valid:        io_redirect_valid,
                          robIdx_flag:  io_redirect_bits_robIdx_flag,
                          robIdx_value: io_redirect_bits_robIdx_value,
                          level:        io_redirect_bits_level};

  // ---------------------------------------------------------------------------
  // 条目阵列的接口信号（每条目一份；1 位的用 packed 向量，结构体用非打包数组）
  // ---------------------------------------------------------------------------
  logic [NUM_ENTRIES-1:0] ent_req_valid;      // 本拍往该条目写一条新请求
  lqu_ent_req_t           ent_req_bits   [NUM_ENTRIES];
  logic [NUM_ENTRIES-1:0] ent_flush;          // 条目本拍作废/退休（释放回 FreeList）
  logic [NUM_ENTRIES-1:0] ent_mmio_sel;       // 条目装着一条已离开 idle 的 MMIO
  logic [NUM_ENTRIES-1:0] ent_slave_valid;    // 条目已认领 Uncache 的 idResp
  logic [ENT_IDX_W-1:0]   ent_slave_id   [NUM_ENTRIES];
  logic [NUM_ENTRIES-1:0] ent_mmio_ready;
  logic [NUM_ENTRIES-1:0] ent_mmio_valid;
  lqu_mmio_out_t          ent_mmio_bits  [NUM_ENTRIES];
  lqu_raw_t               ent_raw        [NUM_ENTRIES];
  logic [NUM_ENTRIES-1:0] ent_nc_ready;
  logic [NUM_ENTRIES-1:0] ent_nc_valid;
  lqu_nc_out_t            ent_nc_bits    [NUM_ENTRIES];
  logic [NUM_ENTRIES-1:0] ent_ureq_ready;
  logic [NUM_ENTRIES-1:0] ent_ureq_valid;
  lqu_ent_ureq_t          ent_ureq_bits  [NUM_ENTRIES];
  logic [NUM_ENTRIES-1:0] ent_idresp_valid;
  logic [NUM_ENTRIES-1:0] ent_resp_valid;
  logic [NUM_ENTRIES-1:0] ent_exc_valid;
  lqu_exc_t               ent_exc_bits   [NUM_ENTRIES];

  // ---------------------------------------------------------------------------
  // §1 s1：三条请求按年龄排序（utility HwSort，3 输入版）
  //
  // precedes[j][i] = 输入 j 应排在输入 i 前面：有效的排在无效的前面；都有效时 robIdx
  // 更老的在前；都无效时编号小的在前。rank[i] = 排在 i 前面的个数 = i 的输出槽号，
  // 输出槽 k 取 rank == k 的那个输入（sel[k][j]，Mux1H：按位或）。
  // ---------------------------------------------------------------------------
  logic       precedes [LD_W][LD_W];
  logic [1:0] rank     [LD_W];
  logic       sel      [LD_W][LD_W];   // sel[k][j]：输出槽 k 选输入 j
  logic [LD_W-1:0] s1_valid;
  lqu_req_t   s1_req   [LD_W];

  always_comb begin
    for (int i = 0; i < LD_W; i++)
      for (int j = 0; j < LD_W; j++)
        precedes[j][i] = 1'b0;
    for (int i = 0; i < LD_W; i++) begin
      for (int j = i + 1; j < LD_W; j++) begin
        // Sort.scala shouldSwap(x_i, x_j)：j 该换到 i 前面
        precedes[j][i] = (~io_req_valid[i] & io_req_valid[j])
                       | (io_req_valid[i] & io_req_valid[j]
                          & rob_is_before(io_req_bits[j].uop_robIdx_flag, io_req_bits[j].uop_robIdx_value,
                                          io_req_bits[i].uop_robIdx_flag, io_req_bits[i].uop_robIdx_value));
        precedes[i][j] = ~precedes[j][i];
      end
    end
    for (int i = 0; i < LD_W; i++) begin
      rank[i] = 2'd0;
      for (int j = 0; j < LD_W; j++)
        rank[i] = rank[i] + {1'b0, precedes[j][i]};
    end
    for (int k = 0; k < LD_W; k++) begin
      s1_valid[k] = 1'b0;
      s1_req[k]   = '0;
      for (int j = 0; j < LD_W; j++) begin
        sel[k][j]   = (rank[j] == 2'(k));
        s1_valid[k] = s1_valid[k] | (sel[k][j] & io_req_valid[j]);
        s1_req[k]   = s1_req[k] | ({$bits(lqu_req_t){sel[k][j]}} & io_req_bits[j]);
      end
    end
  end

  // ---------------------------------------------------------------------------
  // §2 s2：打一拍，判定每条能不能入队
  //
  // s2_valid = RegNext(s1_valid) 且 没被 上一拍的 redirect（每 lane 各打一份）或本拍
  // redirect 冲掉。能入队 = s2_valid、没有 load 异常（LduCfg 关心的 6 个异常位）、
  // 不需要重放（rep_info 11 个原因位）、确实是 mmio 或 nc。
  // ---------------------------------------------------------------------------
  logic [LD_W-1:0] s2_valid_q;           // RegNext(s1_valid)（不复位）
  redirect_t       s2_redirect_q [LD_W]; // RegNext(io.redirect)，每 lane 一份（不复位）
  lqu_req_t        s2_req_q      [LD_W]; // RegEnable(s1_req, s1_valid)（不复位）

  always_ff @(posedge clock) begin
    for (int k = 0; k < LD_W; k++) begin
      s2_valid_q[k]    <= s1_valid[k];
      s2_redirect_q[k] <= redirect_now;
      if (s1_valid[k])
        s2_req_q[k] <= s1_req[k];
    end
  end

  logic [LD_W-1:0] s2_valid;
  logic [LD_W-1:0] s2_has_exception;
  logic [LD_W-1:0] s2_need_replay;
  logic [LD_W-1:0] s2_enqueue;

  always_comb begin
    for (int k = 0; k < LD_W; k++) begin
      s2_valid[k] = s2_valid_q[k]
                  & ~need_flush(s2_req_q[k].uop_robIdx_flag, s2_req_q[k].uop_robIdx_value, s2_redirect_q[k])
                  & ~need_flush(s2_req_q[k].uop_robIdx_flag, s2_req_q[k].uop_robIdx_value, redirect_now);
      // ExceptionNO.selectByFu(exceptionVec, LduCfg)：load 地址不对齐(4)/访问错(5)/页错(13)/
      // 断点(3)/硬件错(19)/客户页错(21)
      s2_has_exception[k] = |{s2_req_q[k].uop_exceptionVec_21, s2_req_q[k].uop_exceptionVec_19,
                              s2_req_q[k].uop_exceptionVec_13, s2_req_q[k].uop_exceptionVec_5,
                              s2_req_q[k].uop_exceptionVec_4,  s2_req_q[k].uop_exceptionVec_3};
      s2_need_replay[k]   = |{s2_req_q[k].rep_info_cause_10, s2_req_q[k].rep_info_cause_9,
                              s2_req_q[k].rep_info_cause_8,  s2_req_q[k].rep_info_cause_7,
                              s2_req_q[k].rep_info_cause_6,  s2_req_q[k].rep_info_cause_5,
                              s2_req_q[k].rep_info_cause_4,  s2_req_q[k].rep_info_cause_3,
                              s2_req_q[k].rep_info_cause_2,  s2_req_q[k].rep_info_cause_1,
                              s2_req_q[k].rep_info_cause_0};
      s2_enqueue[k] = s2_valid[k] & ~s2_has_exception[k] & ~s2_need_replay[k]
                    & (s2_req_q[k].mmio | s2_req_q[k].nc);
    end
  end

  // ---------------------------------------------------------------------------
  // §3 分配条目：FreeList 一拍最多给 3 个空槽（allocateSlot(0..2)，canAllocate 标出前几个
  // 可用）。第 w 条要入队的请求用第 offset(w) 个空槽，offset = 它前面要入队的条数。
  // 拿到槽 = s2_enq_valid；要入队却没拿到 = 满了，去 §9 回滚。
  // 写条目：同一条目若被多个 lane 同时指到（不会发生），编号大的 lane 赢（Scala when 次序）。
  // ---------------------------------------------------------------------------
  logic [LD_W-1:0]      fl_can_alloc;
  logic [ENT_IDX_W-1:0] fl_slot [LD_W];
  logic [1:0]           alloc_offset [LD_W];
  logic [LD_W-1:0]      s2_enq_valid;
  logic [ENT_IDX_W-1:0] s2_enq_index [LD_W];
  logic [NUM_ENTRIES-1:0] ent_free;

  always_comb begin
    for (int w = 0; w < LD_W; w++) begin
      alloc_offset[w] = 2'd0;
      for (int v = 0; v < w; v++)
        alloc_offset[w] = alloc_offset[w] + {1'b0, s2_enqueue[v]};
      s2_enq_valid[w] = 1'b0;
      s2_enq_index[w] = '0;
      for (int o = 0; o < LD_W; o++) begin
        if (alloc_offset[w] == 2'(o)) begin
          s2_enq_valid[w] = s2_enqueue[w] & fl_can_alloc[o];
          s2_enq_index[w] = fl_slot[o];
        end
      end
    end
  end

  always_comb begin
    for (int i = 0; i < NUM_ENTRIES; i++) begin
      ent_req_valid[i] = 1'b0;
      ent_req_bits[i]  = to_ent_req(s2_req_q[0]);
      for (int w = 0; w < LD_W; w++) begin
        if (s2_enq_valid[w] && s2_enq_index[w] == ENT_IDX_W'(i)) begin
          ent_req_valid[i] = 1'b1;
          ent_req_bits[i]  = to_ent_req(s2_req_q[w]);
        end
      end
    end
  end

  FreeList_6 freeList (
    .clock             (clock),
    .reset             (reset),
    .io_allocateSlot_0 (fl_slot[0]),
    .io_allocateSlot_1 (fl_slot[1]),
    .io_allocateSlot_2 (fl_slot[2]),
    .io_canAllocate_0  (fl_can_alloc[0]),
    .io_canAllocate_1  (fl_can_alloc[1]),
    .io_canAllocate_2  (fl_can_alloc[2]),
    .io_doAllocate_0   (s2_enq_valid[0]),
    .io_doAllocate_1   (s2_enq_valid[1]),
    .io_doAllocate_2   (s2_enq_valid[2]),
    .io_free           (ent_free),
    .io_validCount     (),   // 只供 perf（QueuePerf），不接
    .io_empty          ()
  );

  // ---------------------------------------------------------------------------
  // §4 条目阵列：16 个 UncacheEntry（每个只差 ENTRY_ID）
  //
  // 每个条目的控制输入：
  //   idResp —— 只有 mid == 条目号的那个条目看得到 valid（bits 广播）；
  //   resp   —— 只有已认领且 slaveId == resp.id 的条目看得到 valid（bits 广播）；
  //   写回 ready / 请求 ready —— 见 §5 / §6。
  // ---------------------------------------------------------------------------
  always_comb begin
    for (int i = 0; i < NUM_ENTRIES; i++) begin
      ent_idresp_valid[i] = (io_uncache_idResp_bits_mid == 7'(i)) & io_uncache_idResp_valid;
      ent_resp_valid[i]   = ent_slave_valid[i] & (ent_slave_id[i] == io_uncache_resp_bits_id)
                          & io_uncache_resp_valid;
    end
  end

