    mmio_pipe_in_valid = ent_mmio_sel[0] & ent_mmio_valid[0];
    mmio_pipe_in_bits  = ent_mmio_bits[0];
    mmio_raw           = ent_raw[0];
    for (int i = 1; i < NUM_ENTRIES; i++) begin
      if (ent_mmio_sel[i]) begin          // 编号大的覆盖编号小的
        mmio_idx           = ENT_IDX_W'(i);
        mmio_ureq_valid    = ent_ureq_valid[i];
        mmio_ureq_bits     = ent_ureq_bits[i];
        mmio_pipe_in_valid = ent_mmio_valid[i];
