    nc_grp_is_mmio = '0;
    for (int g = 0; g < NC_GROUPS; g++) begin
      nc_grp_bits[g] = '0;
      for (int i = g; i < NUM_ENTRIES; i += NC_GROUPS) begin
        if (ent_nc_valid[i] & ~nc_grp_any[g]) begin
          nc_first[i]       = 1'b1;
          nc_grp_any[g]     = 1'b1;
          nc_grp_is_mmio[g] = ent_mmio_sel[i];
          nc_grp_bits[g]    = ent_nc_bits[i];
