    end
    // 0 号口不接任何条目（golden：io_in_valid = 0、payload 全 0）
    nc_pipe_in_valid[0] = 1'b0;
    nc_pipe_in_bits[0]  = '0;
    for (int g = 0; g < NC_GROUPS; g++) begin
